:root {
  color-scheme: light;
  --paper: #fff9db;
  --surface: #ffffff;
  --ink: #292447;
  --muted: #635b78;
  --line: #ded6ef;
  --green: #6640c8;
  --green-hover: #4e2cab;
  --tint: #eee6ff;
  --orange: #a52364;
  --pink: #ff96c1;
  --yellow: #ffe46a;
  --mint: #d4f5dc;
  --radius: 16px;
  font-family: 'DM Sans', sans-serif;
  color: var(--ink);
  background: var(--paper);
  font-synthesis: none;
}
.primary { background: var(--green); color: #fff; min-height: 52px; transition: background .16s ease-out, transform .16s ease-out; }

